    title: 'Punk w PRL',
    subtitle: 'Dezerter, Brygada Kryzys i scena niezależna',
    category: 'kultura',
    tags: ['muzyka', 'punk', 'lata 80.', 'kontrkultura', 'młodzież'],
    yearStart: 1980,
